#include <bits/stdc++.h>
using namespace std;

int countPossible(char s[]) {
    int ways = 1;
    if (s[0] == '0') {
        return 0;
    }
    if (s[0] == '_') {
        ways *= 9;
    } else if (s[0] == 'X') {
        ways *= 9;
        for (int i = 0; i < strlen(s); i++) {
            if (s[i] == 'X') {
                s[i] = '1';
            }
        }
    }
    for (int i = 1; i < (int)strlen(s); i++) {
        if (s[i] == '_') {
            ways *= 10;
        } else if (s[i] == 'X') {
            ways *= 10;
            for (int j = 0; j < (int)strlen(s); j++) {
                if (s[j] == 'X') {
                    s[j] = '1';
                }
            }
        }
    }
    return ways;
}

void fillWith(char s[], char digit) {
    for (int i = 0; i < (int)strlen(s); i++) {
        if (s[i] == 'X') {
            s[i] = digit;
        }
    }
}

bool canPlace(char s[], int index, char digit) {
    return s[index] == 'X' || s[index] == '_' || s[index] == digit;
}

void assign(char s[], int index, char digit) {
    if (s[index] == 'X') {
        fillWith(s, digit);
    } else {
        s[index] = digit;
    }
}

int main() {
    string line;
    getline(cin, line);
    vector<char> s(line.begin(), line.end());
    int totalWays = 0;
    int len = (int)s.size();

    if (len == 1) {
        if (s[0] == '0' || s[0] == '_' || s[0] == 'X') {
            totalWays = 1;
        }
    } else {
        if (!(s[len - 1] == 'X' && s[len - 2] == 'X')) {
            if (canPlace(s.data(), len - 1, '5') && canPlace(s.data(), len - 2, '2')) {
                vector<char> temp = s;
                assign(temp.data(), len - 1, '5');
                assign(temp.data(), len - 2, '2');
                totalWays += countPossible(temp.data());
            }
            if (canPlace(s.data(), len - 1, '0') && canPlace(s.data(), len - 2, '5')) {
                vector<char> temp = s;
                assign(temp.data(), len - 1, '0');
