                totalWays += countPossible(temp.data());
            }
            if (canPlace(s.data(), len - 1, '5') && canPlace(s.data(), len - 2, '7')) {
                vector<char> temp = s;
                assign(temp.data(), len - 1, '5');
                assign(temp.data(), len - 2, '7');
                totalWays += countPossible(temp.data());
            }
        }
        if (s[len - 1] == 'X' && s[len - 2] == 'X') {
            vector<char> temp = s;
            assign(temp.data(), len - 1, '0');
            totalWays += countPossible(temp.data());
        } else if (canPlace(s.data(), len - 1, '0') && canPlace(s.data(), len - 2, '0')) {
            vector<char> temp = s;
            assign(temp.data(), len - 1, '0');
            assign(temp.data(), len - 2, '0');
            totalWays += countPossible(temp.data());
        }
    }
    cout << totalWays << "\n";
    return 0;
}

